tools.example:
model.component("comp1").physics("fpt").create("df1", "DragForce", 3);
model.component("comp1").physics("fpt").feature("df1").selection().all();
model.component("comp1").physics("fpt").feature("df1").set("DragLaw", "SchillerNaumann");
model.component("comp1").physics("fpt").feature("df1").set("u", new String[]{"u", "v", "w"});  // spf velocity
model.component("comp1").physics("fpt").feature("df1").set("TurbulentDispersionModel", "DiscreteRandomWalk");
// Application Library: Particle_Tracing_Module/Fluid_Flow/flow_channel_turbulent_dispersion

model.component("comp1").physics("cpt").create("ef1", "ElectricForce", 3);
model.component("comp1").physics("cpt").feature("ef1").selection().all();
model.component("comp1").physics("cpt").feature("ef1").set("SpecifyForceUsing", "ElectricPotential");
model.component("comp1").physics("cpt").feature("ef1").set("TimeDependenceOfField", "TimeHarmonic");
// select V from Electrostatics in the GUI; Application Library: quadrupole_mass_filter, rfq_ion_trap

model.component("comp1").physics("cpt").create("mf1", "MagneticForce", 3);
model.component("comp1").physics("cpt").feature("mf1").selection().all();
model.component("comp1").physics("cpt").feature("mf1").set("B", new String[]{"0", "0", "0.1[T]"});  // cyclotron motion
// Application Library: ion_cyclotron_motion, magnetic_lens, trapped_protons (Earth's field)

model.component("comp1").physics("fpt").create("vfc1", "VolumeForceCalculation", 3);
model.component("comp1").physics("fpt").feature("vfc1").selection().all();
// compare fpt.vfc1.F magnitude with pressure gradients to judge coupling strength

model.study().create("std1");
model.study("std1").create("bcpt", "BidirectionallyCoupledParticleTracing");
model.study("std1").feature("bcpt").set("tlist", "range(0,1e-10,5e-8)");
model.study("std1").run();
// Application Library: electron_beam_divergence, pierce_electron_gun, planar_diode

model.result().create("pg3", "PlotGroup2D");
model.result("pg3").set("data", "part1");
model.result("pg3").create("phpo1", "PhasePortrait");
// Manual axes: x = cpt.qx, y = cpt.vx/cpt.vz (x-x' phase space)
// Application Library: ion_funnel, rfq_ion_trap, ideal_cloak

model.result().dataset().create("cpl1", "CutPlane");
model.result().dataset("cpl1").set("data", "part1");
model.result().create("pg4", "PlotGroup3D");
model.result("pg4").set("data", "cpl1");
model.result("pg4").create("poma1", "PoincareMap");
// Application Library: laminar_mixer_particle, magnetic_lens

model.component("comp1").physics("fpt").prop("RandomNumberArgs").set("RandomNumberArgs", "UserDefined");
model.component("comp1").physics("fpt").feature("bf1").set("i", "seed");
model.param().set("seed", "1");
// Study > Parametric Sweep over seed = range(1,1,20) for 20 Brownian realizations
